}
md <- c(md,"",
  "All74 unique identifiers were mapped in two batches, then verified against exact UniProt STRING cross-references. Curated JE2 identities avoid five ineligible alternate reference matches in the full map. The fresh49 network exactly reproduces the204 edges and scores of the user's original export.","",
