  paste0("- [67-protein PNG](",fig,"STRING_67_poster_halos.png), [PDF](",fig,"STRING_67_poster_halos.pdf), [SVG](",fig,"STRING_67_poster_halos.svg)."),
  paste0("- [Open the49 network on STRING](",links[[1]],")."),
